export const content: ContentItem[] = [
  { slug: 'how-to-choose-web-development-company-kenya', type: 'article', title: 'How to Choose a Web Development Company in Kenya', excerpt: 'The questions that separate agencies who ship from agencies who disappear — what to ask, which red flags to walk away from, and the seven clauses a proper contract must contain.', category: 'Web Development & Technology', date: '2026-10-03', dateModified: '2026-10-03', readTime: '9 min read', author: 'Lumyn Studio', image: '/images/articles/choose-dev-company-hero.svg', cluster: 'business-website', relatedSlugs: ['website-cost-kenya-2026', 'custom-website-vs-wordpress-kenya', 'why-kenyan-business-needs-professional-website-2026'], faq: [
    { question: 'How much should I pay a web development company in Kenya?', answer: 'A freelancer or small studio typically charges KES 80,000–400,000. An established agency runs KES 400,000–1,500,000. A custom platform or product-grade build starts at KES 1,500,000. Quote differences usually mean scope differences, not value differences — compare scopes, never prices alone.' },
    { question: 'How long does a business website take to build?', answer: 'A brochure site takes 3–6 weeks. A CMS-driven business site with real content takes 6–10 weeks. A custom platform with authentication, dashboards and M-Pesa flows takes 3–6 months. Anyone promising a five-page business site in two weeks is either templating it or under-quoting the content.' },
    { question: 'Should I pay the full project cost upfront?', answer: 'No. A normal structure is 30–40% to start, milestone payments against deliverables, and the balance on handover after you have accepted the site. Full payment before any design or build work exists should end the conversation.' },
    { question: 'How do I check that a web development company is legitimate?', answer: 'Verify a physical address, ask for a live URL you can visit yourself rather than screenshots, request references you can actually call, confirm they will register your domain in your company name, and check their certificate of registration. A portfolio of live sites you can inspect beats a portfolio of images.' },
    { question: 'Do I need a contract, or is a written quote enough?', answer: 'Sign a contract. A quote states a price; a contract states scope, ownership, payment milestones, support, and exit terms. Without those, a disagreement becomes an argument about what everyone assumed was included.' },
  ], content: [
    'Most businesses do not lose money on websites because they picked the wrong platform. They lose money because they bought a quote instead of a capability. The site launches, it looks reasonable, and then nobody can change a price, nothing ranks on local search, and the phone number baked into the hero image is six months out of date.',
    '<strong>Start with the outcome, not the stack</strong>Before you compare a single proposal, write down what the website has to do for the business — with a number attached. "Get more bookings" is not a requirement. "Receive 15 enquiries a month from Google and WhatsApp at a cost per enquiry under KES 500" is. When you write requirements that specific, half the quotes disqualify themselves in the first conversation, and the survivors are actually worth comparing.',
    '<strong>Ask how they work before you ask what it costs</strong>Delivery answers tell you more about outcomes than a price list does. Ask every candidate the same things, in the same order, and write the answers down. <ol><li><strong>Who exactly will work on my project?</strong> Names, roles, and whether they are employees or subcontractors.</li><li><strong>Can I speak to a client with a project like mine?</strong> Not a logo wall — a reference who will describe what went wrong as well as what worked.</li><li><strong>What do the first two weeks look like?</strong> If week one is "we start designing", you are being sold pixels, not outcomes.</li><li><strong>How is content handled?</strong> Who writes it, what happens when it is not ready at launch, and who proofreads the final copy.</li><li><strong>What is your defect window?</strong> Thirty days of bug fixes after launch is normal. Ninety days of free feature work means the scope was priced wrong.</li><li><strong>Who owns the code and the accounts?</strong> Domain, hosting, analytics, Search Console, CMS admin, design files.</li><li><strong>What does support cost after launch?</strong> Hourly, monthly, or nothing. "Nothing at all" is an answer.</li></ol>',
    '<strong>Ask about the work, not the tools</strong>Technology choices matter only where they change your outcome. Questions that separate serious candidates from the rest: <ul><li>Will the site load in under three seconds on a KES 15,000 Android handset on 3G? Have you measured it, or only looked at it on a laptop?</li><li>How will M-Pesa payments work here — STK Push, redirect, or a till number? Who holds the Safaricom account?</li><li>What happens to my content, domain, and customer data if we stop working together tomorrow?</li><li>Which parts of this site are custom code, and which could my own team edit?</li><li>How will search engines read this site, and what will you set up so I appear for the searches my customers actually make?</li><li>What will you hand over at the end, and in what format?</li></ul>',
    '<strong>Red flags that should end the conversation early</strong><ul><li>Quoting without asking a single question about your business, your customers, or your competitors.</li><li>A price with no scope attached — no page list, no feature list, no exclusions.</li><li>"Unlimited revisions" or "unlimited pages" in writing.</li><li>Registering your domain later, or in the agency\'s name, so the first site can launch this week.</li><li>Showing you other clients\' projects but not a live URL you can open yourself.</li><li>100% payment before any design or build work exists.</li><li>Vague answers about who does the work, dressed up as phrases like "our partner network".</li><li>A proposal that is a PDF of screenshots with no written scope at all.</li></ul>',
    '<strong>Understand what you are actually paying for</strong>A quote should be a breakdown, not a number. If nobody can tell you where the money goes, the number is a starting position in a negotiation you have not noticed yet. Honest breakdowns separate design, engineering, content, integrations, and ongoing costs — the same four cost levers we use in <a href="/articles/website-cost-kenya-2026">what a website actually costs in Kenya in 2026</a>. Two things quietly inflate every quote: a brief that says "make it modern and professional", which produces a design budget nobody can verify, and a scope that omits content, which then becomes half the build.',
    '<strong>Read the contract for these seven clauses</strong><ol><li><strong>Ownership.</strong> Code, design files, and content become yours on final payment, stated in writing.</li><li><strong>Accounts in your company name.</strong> Verify the domain registration before the second instalment, not after launch.</li><li><strong>Scope with exclusions.</strong> What is included, what is explicitly not, and what triggers a change request.</li><li><strong>Milestones tied to deliverables.</strong> Never more than 40% upfront, with the balance on handover after you accept the site.</li><li><strong>Support terms.</strong> What is covered, for how long, at what response time, and at what rate afterwards.</li><li><strong>Handover.</strong> Source code, credentials, documentation, and a walkthrough with the people who will use it.</li><li><strong>Exit clause.</strong> What you may take with you, and in what format, if the relationship ends early.</li></ol>',
    '<strong>The Kenyan-specific questions most buyers skip</strong><ul><li><strong>Who holds the Safaricom Daraja account?</strong> Production credentials must live with your business, not the agency. Sandbox testing is not go-live testing.</li><li><strong>What is your position on the Data Protection Act?</strong> Consent, retention, and where customer data physically sits all matter under active ODPC enforcement.</li><li><strong>Where is the site served from?</strong> Local hosting versus offshore CDN changes latency and data residency.</li><li><strong>How was it tested on real devices and real networks?</strong> A Tecno or Infinix on 3G is your actual customer.</li><li><strong>Who supports it when you are open and they are not?</strong> Kenyan business hours span Nairobi to Lamu.</li><li><strong>Can your team support it in Swahili?</strong> Not every page needs it, but onboarding and support usually do.</li></ul>',
    '<strong>Get three quotes and compare them the same way</strong>Ask each candidate for the same deliverable in the same format: a scope list, a line-item breakdown, a timeline with milestones, and a support proposal. Then score them identically. Do not compare a KES 180,000 proposal against a KES 900,000 one on price alone — they may be pricing different products, and the cheaper one may simply be missing the things that decide whether the site works.',
    '<strong>What a proper handover looks like</strong><ul><li>Source code and design files in your own repository or storage, with history</li><li>Domain, hosting, DNS, CMS, analytics, and Search Console accounts owned by you</li><li>A document explaining how to publish a page, add a service, and change a price</li><li>A training session with the people who will actually use it</li><li>A support window with a named contact and a stated response time</li><li>A visible backup and update routine, including who holds the credentials</li></ul>',
    '<strong>A scoring rubric you can use today</strong><ol><li>Quality of their questions about your business (0–10)</li><li>Quality of relevant work, verified on live URLs (0–10)</li><li>The team who will do the work, and their availability (0–10)</li><li>Contract and ownership terms (0–10)</li><li>Three-year total cost of ownership, not just the build price (0–10)</li></ol>If two candidates finish within one point of each other, choose the one who will still answer the phone in twelve months. That is the decision.',
    'The cheapest quote is usually the most expensive option once you count a site nobody can update, nobody can find, and that cannot take a payment. Choose a team that can explain what your website must do for the business, show you work you can verify, and hand you the keys when it is done. If you want that conversation, <a href="/articles/10-features-every-business-website-should-have">here is what a business website should include</a> before you sign anything, and <a href="/contact">we are happy to walk through it with you</a>.',
  ] },
  { slug: 'website-vs-social-media-kenya', type: 'article', title: 'Website vs Social Media: What Does Your Business Actually Need?', excerpt: 'Social media creates attention. A website converts it and keeps it. An honest look at when each one is enough, when each one is costing you money, and the order that works for Kenyan businesses.', category: 'Business & Digital Transformation', date: '2026-10-03', dateModified: '2026-10-03', readTime: '8 min read', author: 'Lumyn Studio', image: '/images/articles/website-vs-social-hero.svg', cluster: 'business-website', relatedSlugs: ['why-kenyan-business-needs-professional-website-2026', '10-features-every-business-website-should-have', 'website-cost-kenya-2026'], comparisonTable: {
    caption: 'Website vs social media — what each channel actually does for a business',
    headers: ['Need', 'Social media', 'Website'],
    rows: [
      ['Be found when people search', 'No search visibility', 'Indexed, ranked, and cited'],
      ['Own your audience', 'No — the platform can change the rules', 'Yes — you own the asset and the data'],
      ['Cost to start', 'Low, mostly time', 'KES 80,000+ for a credible build'],
      ['Ongoing effort', 'Daily posting, or the page dies', 'Monthly updates and improvements'],
      ['Take a payment', 'Redirects out to another app', 'M-Pesa, card, transfer, in context'],
      ['Prove you are real', 'Follower counts, which can be bought', 'Registration, reviews, address, schema'],
      ['Survives a staff change', 'Often does not', 'Documented, transferable, yours'],
      ['Best at', 'Demand generation and community', 'Conversion, trust, and search visibility'],
    ],
  }, faq: [
    { question: 'Do I need a website if I already have a lot of followers?', answer: 'Followers are rented attention, and most businesses with large followings still lose every search for their own service. If your customers search before they buy, the website is what converts that search. Keep the accounts — add the site as the place the audience lands.' },
    { question: 'How much should a Kenyan business spend on social media versus a website?', answer: 'Social needs consistency and an owner more than budget. A credible website costs KES 80,000–400,000 through a small studio and KES 400,000–1,500,000 through an agency. Spend on the asset you own, then on the attention that drives people to it.' },
    { question: 'Which platform should a Kenyan business focus on?', answer: 'It depends on who you sell to: WhatsApp for direct conversations and repeat orders, Instagram for visual products, Facebook for family and older audiences, TikTok for discovery with younger demographics, LinkedIn for B2B and professional services. Most businesses need two well-run channels, not five neglected ones.' },
    { question: 'Is WhatsApp Business enough instead of a website?', answer: 'It is the closest substitute many small businesses will find — conversations, catalogues, payments, and orders in one place. What it cannot do is rank in search, host structured content that search engines and AI assistants can read, or present your full offer without scrolling a chat thread.' },
    { question: 'Can social media drive sales if I never build a website?', answer: 'Yes, at low volume. But every sale made through a platform is a sale you do not own: no customer list, no search visibility to fall back on, and no checkout you control. Most businesses that plateau hit exactly this ceiling.' },
  ], content: [
    'The honest answer is that this is not a choice. Social media is where people find you. A website is where they decide whether you are real. Kenyan businesses that pick one usually end up paying for both — just later, and at a higher price.',
    '<strong>What social media actually does for you</strong><ul><li>Gives you reach you did not pay for, and fast feedback on what people respond to.</li><li>Builds a visible presence in a specific neighbourhood, campus, or industry group.</li><li>Costs almost nothing to start, which is why nearly every business begins here.</li><li>Creates a record of your work — photos, before-and-afters, testimonials — that sells passively.</li><li>Is where most Kenyan buying conversations happen today, including on WhatsApp.</li></ul>The failure mode is equally clear: you own neither the audience nor the reach nor the history. The page is worth nothing if the account is lost, the algorithm changes, or the employee who ran it leaves.',
    '<strong>What a website actually does for you</strong><ul><li>Shows up when someone searches for what you sell. That demand already exists and does not need advertising.</li><li>Proves existence, legitimacy, and permanence — especially for customers who have never heard of you.</li><li>Holds the full version of the offer: services, prices, process, evidence, FAQs, and every contact route.</li><li>Gives you data on what people read, click, and enquire about.</li><li>Accepts payments and bookings without sending the customer into a third-party app.</li></ul>',
    '<strong>When social media is genuinely enough</strong><ul><li>You launched less than two years ago and are still working out what you sell.</li><li>You serve one neighbourhood or one niche, and your customers already know you.</li><li>Your transactions happen on WhatsApp anyway and closing there is faster than any checkout.</li><li>Your total digital budget right now is under roughly KES 50,000 a year.</li><li>You need evidence of demand before committing to a build.</li></ul>Social-first is a legitimate strategy for many informal retailers, food businesses, and trades. It is a choice, not a failure — as long as it is a deliberate one.',
    '<strong>When social-only is quietly costing you money</strong><ul><li>A competitor appears on Google for the service you sell, and you do not appear at all.</li><li>Your enquiries come from whatever the algorithm decided to show that week.</li><li>Nobody on your team can change the page, so a price change takes a week and a WhatsApp message.</li><li>The account lives on one person\'s phone, under one person\'s name.</li><li>Customers cannot pay you from the page — they have to leave, and most of them do not come back.</li><li>You want to be found by AI assistants and answer engines, which read structured websites, not feeds.</li></ul>This is the same credibility gap we wrote about in <a href="/articles/why-kenyan-business-needs-professional-website-2026">why every Kenyan business needs a professional website</a>, seen from the business that decided a page was enough.',
    '<strong>The order that works</strong><ol><li><strong>Claim and complete your Google Business Profile.</strong> Free, and often the fastest win in local search.</li><li><strong>Ship a small website that does the basics properly.</strong> Mobile-fast, one-tap contact, services and prices, proof, and a form that reaches a human.</li><li><strong>Keep social as the demand engine.</strong> Point every post at something specific on the site: the feed creates attention, the site converts it.</li><li><strong>Add money.</strong> M-Pesa deposits, bookings, or ordering. Payments are where a website starts paying for itself.</li><li><strong>Add content, then optimise.</strong> Publish what customers actually ask, then fix the technical layer underneath.</li></ol>',
    '<strong>How to use each one properly</strong>On social: post work, not slogans. Reply to comments and DMs within a day. Use WhatsApp Business with a catalogue so people can browse and order without a PDF. Link to one specific page per post, not the homepage. On the website: one clear action per page, fast loads on 3G, a phone number and WhatsApp button that work in a thumb, and prices or ranges left visible. The two channels are only useful together if the journey between them is short.',
    '<strong>The cost of getting this wrong</strong>Social-first is the right first move for many businesses and the wrong place to stop. The expensive version of the mistake shows up later: no search visibility to fall back on, no customer data you own, and no way to take a payment without losing part of the sale. A credible business website in Kenya runs from KES 80,000 to KES 1,500,000+ depending on scope — see <a href="/articles/website-cost-kenya-2026">what a website costs in Kenya</a> — and it is the cheapest insurance most SMEs buy. Local search in particular compounds: a business that starts now is usually ranking while competitors are still deciding.',
    'Social media gets you attention. A website converts it, proves you are real, and keeps working after the algorithm moves on. Most Kenyan businesses that grow past a single location run both. If you want to know which one comes first for you, <a href="/articles/10-features-every-business-website-should-have">start with the essentials here</a>, then <a href="/contact">talk to us about the order that fits your business</a>.',
  ] },
  { slug: '10-features-every-business-website-should-have', type: 'article', title: '10 Features Every Modern Business Website Should Have', excerpt: 'Speed, one-tap contact, native M-Pesa, local search, and a CMS your team can actually use. The ten features that separate a website that works from one that merely exists.', category: 'Business & Digital Transformation', date: '2026-10-03', dateModified: '2026-10-03', readTime: '8 min read', author: 'Lumyn Studio', image: '/images/articles/website-features-hero.svg', cluster: 'business-website', relatedSlugs: ['how-to-choose-web-development-company-kenya', 'website-cost-kenya-2026', 'mpesa-integration-lessons'], faq: [
    { question: 'How much do these features add to a website cost in Kenya?', answer: 'Most are included in a standard business build. The ones that add real cost are native M-Pesa integration with reconciliation, a custom CMS or dashboard, and e-commerce or large content volumes. A credible small-business site covering speed, contact, trust, and an editable CMS typically lands between KES 80,000 and KES 400,000.' },
    { question: 'Do I need all ten features before launch?', answer: 'No. Speed, contact, and trust should exist before you launch. The rest can follow. Going live with a fast, contactable, credible site and adding payments, analytics, and SEO a month later beats delaying everything for a longer build.' },
    { question: 'Which single feature matters most?', answer: 'Speed, measured on a real phone over a real network. Every other feature is only reachable if the page loads. A beautiful site nobody waits for has no features at all.' },
    { question: 'Can these features be added to an existing website later?', answer: 'Usually yes — analytics, schema, trust signals, and payments can be added without a rebuild. Speed, CMS usability, and mobile design are structural: if they are wrong, they usually justify rebuilding.' },
    { question: 'How do I check whether my current website already has them?', answer: 'Run the ten-minute audit in this article. It covers load time on mobile data, tap-to-call and tap-to-WhatsApp, form delivery, local search visibility, edit access without a developer, visible trust signals, whether prices are on the page, and the SEO basics.' },
  ], content: [
    'A business website in 2026 is not a brochure with a contact form. It is the only piece of digital infrastructure most Kenyan businesses fully own, and it has specific jobs: load fast on a cheap phone, get found locally, take a payment, prove you are real, and be editable without a developer. These ten features separate a website that works from one that only exists.',
    '<strong>1 — Loads in under three seconds on a real phone</strong>Most Kenyan internet access is mobile, much of it on mid-range handsets and 3G. A site that takes six seconds to become usable on a Tecno Spark loses most of its visitors before it paints. Ask to see load times measured on a real device over a real network, not on office fibre. Compressed images, no heavy page builder, minimal third-party scripts, and image sizes that match the layout are what buy those seconds.',
    '<strong>2 — Contact that works in one tap</strong>Click-to-call, click-to-WhatsApp, click-to-map, and a form that reaches a named person with the message intact. Forms that quietly send nothing are the most common failure in Kenyan business websites. Test the form on mobile data before launch, and make sure it tells the visitor what happens next and when they will hear back.',
    '<strong>3 — M-Pesa payments, integrated natively</strong>If your business takes money online, payment belongs in the flow, not two clicks away. STK Push with proper callback handling, confirmation, reconciliation, and a clear message when something fails — we covered the pattern in <a href="/articles/mpesa-integration-lessons">what three M-Pesa integrations taught us about resilient systems</a>. Redirecting to a till number is fine for a handful of manual orders; for anything else it loses a large share of the intent behind it.',
    '<strong>4 — Local search set up properly</strong>Google Business Profile claimed and completed, consistent name, address, and phone number everywhere online, service areas defined, and local business schema on the site. This is the lowest-cost acquisition channel available to a Kenyan small business and it compounds over 12–24 months. The market context is in <a href="/articles/state-of-digital-business-kenya-2026">the state of digital business in Kenya</a>.',
    '<strong>5 — Analytics and Search Console, actually looked at</strong>GA4 with your conversions defined, Search Console verified, and a monthly fifteen-minute review of what people search, which pages they read, and which ones produce enquiries. Most sites have analytics installed and nobody has ever opened them. Set up means knowing the three numbers that matter to your business, not installing a script.',
    '<strong>6 — A CMS your team can use without a developer</strong>Prices, services, photos, and landing pages should be editable in minutes by whoever sells. If every change is a WhatsApp message to the agency, you will stop making changes within a month. Ask to be shown the editing experience during the sales conversation, not explained at handover.',
    '<strong>7 — Trust signals visible without scrolling</strong>A real address, business registration details, verifiable reviews, a named contact with a face and a role, HTTPS, and a visible connection to Kenya. Buyers check these before they message. Reviews do more work than claims: a link to your Google reviews and a visible review count converts better than another paragraph about quality.',
    '<strong>8 — Accessibility as a default</strong>Text that scales, contrast that passes, keyboard navigation, alt text on images, headings in the right order, and tap targets sized for a thumb. Accessibility is not a compliance chore — it is the same discipline as a site that loads quickly on an old phone and stays usable on a bad connection.',
    '<strong>9 — Security, backups, and an update routine</strong>HTTPS everywhere, a maintained CMS, automated backups stored away from the site, a defined update schedule for the platform and any plugins, and credentials held by your business rather than by a freelancer. <a href="/articles/custom-website-vs-wordpress-kenya">Most WordPress risk arrives through plugins</a> — if you take that route, the update routine is not a nicety, it is the job.',
    '<strong>10 — SEO foundations: clean URLs, schema, sitemap, canonicals</strong>A page per service and per location, readable URLs, correct structured data (organisation, local business, service, FAQ), an XML sitemap, canonical tags, and Open Graph images so shared links look intentional. This is not a plugin — it is structure, and it costs hours rather than thousands of shillings.',
    '<strong>Which of the ten does your business actually need?</strong><ul><li><strong>Clinic, law firm, or trades business:</strong> 1, 2, 4, 5, 7. Speed, calls, directions, and reviews — everything else is secondary.</li><li><strong>Retail or e-commerce:</strong> 1, 2, 3, 6, 7. Payments and stock updates are the product.</li><li><strong>B2B or professional services:</strong> 1, 2, 5, 6, 7, 10. Content and search are how buyers find you.</li><li><strong>School, NGO, or community organisation:</strong> 1, 2, 4, 6, 7, 8. Reach, enquiries, and editing by your own team.</li><li><strong>SaaS or platform:</strong> 1, 3, 5, 6, 9, 10. Performance, payments, retention, and security carry the revenue.</li></ul>',
    '<strong>A ten-minute audit you can run yourself</strong><ol><li>Open the site on your phone, on mobile data, and time how long until it is usable.</li><li>Tap the phone number and the WhatsApp button. Both should work immediately.</li><li>Send yourself an enquiry through the form and wait for it to arrive.</li><li>Search your business name plus your service in your town. Do you appear?</li><li>Open Search Console and admit whether you have ever looked at it.</li><li>Find the price of your most common service. If it is not on the site, that is your first fix.</li><li>Check whether someone who did not build the site could change a price without help.</li><li>Look for business registration details and real, reviewable customer feedback.</li></ol>If you could not complete a step, that is the feature you are missing.',
    '<strong>If you are missing half of them</strong>You do not need everything at once, and you should not pay for everything at once. Most Kenyan businesses need 1 to 3, plus 6 and 7, to operate, and 4, 5, and 10 to grow. If a quote includes all ten, ask which are relevant to your next twelve months and which are padding. If a quote excludes speed, payments, or a usable CMS, the price is not low — it is unfinished. <a href="/articles/how-to-choose-web-development-company-kenya">How to choose a web development company in Kenya</a> covers how to compare proposals properly, and <a href="/articles/website-cost-kenya-2026">what a website costs in Kenya</a> covers what each tier of build actually includes.',
    'None of these ten features is exotic. That is the point. They are the difference between a website that generates enquiries and one that exists. If you want them scoped honestly for your business rather than sold to you as extras, <a href="/contact">bring us the requirements</a> and we will tell you which ones actually change your results.',
  ] },
  { slug: 'how-to-choose-web-development-company-kenya', type: 'article', title: 'How to Choose a Web Development Company in Kenya', excerpt: 'A practical framework for evaluating web development companies in Kenya — what to ask, what to look for, and the red flags that separate a real partner from a risky hire.', category: 'Web Development & Technology', date: '2026-10-06', readTime: '11 min read', author: 'Lumyn Engineering', image: '/images/articles/choose-dev-company-hero.svg', cluster: 'business-website', relatedSlugs: ['website-cost-kenya-2026', 'custom-website-vs-wordpress-kenya', 'why-kenyan-business-needs-professional-website-2026'], faq: [
    { question: 'How much should a business website cost in Kenya in 2026?', answer: 'KES 80,000–400,000 for a freelancer or small agency, KES 400,000–1,500,000 for an agency with project management and support, and KES 1,500,000+ for a custom platform. Hidden costs add 20–30% on top. See our full breakdown in <a href="/articles/website-cost-kenya-2026">how much a website costs in Kenya</a>.' },
    { question: 'Should I hire a freelancer or an agency?', answer: 'Freelancers are cheaper upfront but carry continuity risk — when they disappear, you own a site you cannot update. Agencies cost more because they provide accountability, a defined process, and someone who answers when something breaks. Verify portfolio and client continuity before hiring either.' },
    { question: 'What questions should I ask before signing?', answer: 'Ask for: a written breakdown of every line in the quote, references from two recent clients, how post-launch changes are priced and delivered, who holds the source files and CMS credentials at the end, and what happens if the timeline slips. Vague answers to any of these are a warning.' },
    { question: 'How do I know if a portfolio is real?', answer: 'Live URLs beat screenshots. Open three recent projects on a phone on mobile data, not on office fibre. Ask for a client you can call directly — not a testimonial card. A real portfolio has clients who will speak to you.' },
    { question: 'What is the difference between WordPress and custom development for my business?', answer: 'WordPress is right when content publishing is your main activity and you need non-technical editors to update the site daily. Custom development is right when you need unique workflows, complex integrations, high performance, or full ownership of your technology. We break this down in <a href="/articles/custom-website-vs-wordpress-kenya">custom website vs WordPress</a>.' },
  ], comparisonTable: {
    caption: 'Freelancer vs Agency vs Custom Platform — Kenya 2026',
    headers: ['Factor', 'Freelancer (KES 80K–400K)', 'Agency (KES 400K–1.5M)', 'Custom Platform (KES 1.5M+)'],
    rows: [
      ['Project management', 'Ad hoc or none', 'Dedicated PM, defined timeline', 'Product owner + PM, sprint-based'],
      ['Accountability', 'Single person, variable', 'Company-backed, SLA possible', 'Formal SLA, support contract'],
      ['Design quality', 'Varies widely', 'Consistent, tested', 'Bespoke, user-validated'],
      ['CMS ownership', 'Usually fine', 'Handover document required', 'Full IP, custom admin if needed'],
      ['M-Pesa integration', 'Plugin or custom, inconsistent', 'Standard plugins or custom', 'Native, reconciliation included'],
      ['Speed at launch', 'Depends on choices', 'Usually optimised', 'Edge-hosted, server-rendered'],
      ['3-year cost', 'Hidden maintenance fees', 'Support contract 10–20%', 'Support contract 10–20%, lower stack debt'],
      ['Best for', 'Simple brochure, tight budget', 'Growing business, defined scope', 'SaaS, marketplace, product'],
      ['Biggest risk', 'Continuity', 'Scope creep', 'Budget overrun if scope is unclear'],
    ],
  }, content: [
    'The right web development company does not just build what you asked for. It tells you what you actually need before you ask, scopes it honestly, and delivers something your team can own without a monthly retainer to a third party. That is rare. Most agencies sell what they know how to build, not what your business requires. Here is how to tell the difference before you sign.',
    '<strong>Start with the brief, not the quote</strong>A developer who asks about your customers, your sales process, and what happens when the site goes down before quoting is thinking like a partner. One who asks for the sitemap and the colour palette before the conversation is finished is thinking like an order-taker. The brief shapes the quote. If the quote arrives before the brief, it is an estimate, not a proposal.',
    '<strong>Look at three recent live sites, not a portfolio PDF</strong>Ask for URLs, open them on a phone on mobile data, and time how long until the page is usable. Screenshots lie. Live sites under real network conditions do not. Pay attention to whether the contact form reaches a human, whether the phone number is tappable, and whether the site looks like the business behind it. A portfolio full of templates that load slowly is a warning, not a credential.',
    '<strong>Check what happens after launch</strong>The build is the easy part. The question is whether the site is yours afterwards. Ask: who holds the source files, who owns the CMS credentials, and how much does a text change cost six months after handover. A developer who dodges this question is telling you the site will be a liability within a year. See our breakdown of <a href="/articles/website-cost-kenya-2026">what a website costs in Kenya</a> for what support and ownership realistically include.',
    '<strong>Match the team size to the risk</strong>A freelancer can build a good brochure site. They cannot usually absorb the risk of a complex build, and they do not have a process that survives their absence. An agency costs more because it spreads that risk across a team and a process. A custom platform team costs the most because the product is the asset, not the project. Pick the cheapest option that matches the consequence of failure, not the cheapest option that matches the budget.',
    '<strong>Ask about M-Pesa and payments before the sales conversation ends</strong>If your business takes money online, payment is the most technically sensitive part of the site and the part most developers underestimate. STK Push with idempotency keys, callback verification, reconciliation, and a clear failure message is a reasonable minimum. A developer who says "we will add M-Pesa later" has never built it. We covered the exact pattern in <a href="/articles/mpesa-integration-lessons">what three M-Pesa integrations taught us</a>.',
    '<strong>Test the communication, not the pitch</strong>How quickly do they respond, how clearly do they explain trade-offs, and do they push back on bad ideas or agree to everything? A developer who agrees to everything in the first call will agree to everything in the final invoice. Ask for a change mid-conversation and watch the response. A real partner explains the cost of the change. A risky one agrees and moves the date.',
    '<strong>The reference call is non-negotiable</strong>Ask for two clients whose business is similar to yours. Call them. Ask: did the site arrive on time and on budget, does the form actually deliver enquiries, and would they hire the same team again. The answers will tell you more than any portfolio. A developer who hesitates to provide references is hiding something. A good one offers them.',
    '<strong>Red flags that mean walk away</strong><ul><li>The quote is a single number with no breakdown. You cannot compare what you cannot see.</li><li>The proposal does not name who works on your project day-to-day.</li><li>The timeline is aggressive and there is no buffer for feedback or change.</li><li>They cannot explain how they will measure success beyond "a modern website."</li><li>They propose WordPress for a marketplace, or custom React for a five-page brochure.</li><li>The contract gives them full ownership of the code until the final payment is made.</li></ul>Any one of these is recoverable. Three or more means the engagement will cost more than the price on the quote.',
    '<strong>How to compare the final three proposals</strong>Rank each proposal against six things: clarity of the brief, breakdown of the quote, evidence of relevant work, communication quality, post-launch support terms, and whether the proposed stack matches your actual problem. The cheapest proposal is not the one that wins. The one that answers all six questions honestly usually does. If none of them do, keep looking — the cost of switching mid-project is always higher than the cost of choosing correctly at the start.',
    'If you are still not sure after reading this, <a href="/contact">send us your requirements</a> and we will give you an honest read of the landscape — not a pitch. We have reviewed enough proposals from other teams to know what a good one looks like, and we will tell you if we are not the right fit.',
  ] },
  { slug: 'how-ai-transforming-seo-2026', type: 'article', title: 'How AI Is Transforming SEO in 2026: A Developer\'s Guide', excerpt: 'Google\'s shift to semantic search, the rise of vector embeddings, and why programmatic SEO now requires proprietary data + AI orchestration — not just keyword spinning.', category: 'Engineering & SEO', date: '2026-09-28', dateModified: '2026-09-28', readTime: '12 min read', author: 'Lumyn Engineering', image: '/images/articles/ai-seo-hero.svg', cluster: 'seo-foundations', relatedSlugs: [], faq: [
    { question: 'Does Google penalize AI-generated content?', answer: 'No. Google penalizes low-quality content regardless of origin. The March 2024 update targeted "scaled content abuse" — thin, templated, zero-E-E-A-T pages whether human or AI-written.' },
    { question: 'What is semantic search and how does it differ from keyword search?', answer: 'Semantic search uses vector embeddings to understand conceptual relationships. A query for "running shoes flat feet" maps to concepts like overpronation, arch support, stability shoes — not just keyword matches.' },
    { question: 'What is hybrid search and why is it needed?', answer: 'Combines vector similarity (semantic) with BM25 (exact keyword matching). Pure vector fails on model numbers/SKUs; pure keyword fails on concept queries. Reciprocal Rank Fusion merges both.' },
    { question: 'How do I build a competitive moat in SEO with AI?', answer: 'Proprietary data LLMs cannot access: original research, structured product data, user behavior analytics, expert knowledge, local/geo data. Combine this with AI orchestration + human expertise.' },
    { question: 'What is the minimal viable AI-SEO stack?', answer: 'Vector DB (Qdrant/Pinecone), embedding model (text-embedding-3-small), LLM orchestration (LangChain/custom), keyword data API (DataForSEO), crawler (Playwright), indexing (IndexNow).' },
  ], content: [
    'The SEO landscape has fundamentally shifted. Google\'s March 2024 core update wasn\'t just another algorithm tweak — it signaled the end of traditional keyword-matching search and the beginning of genuine semantic understanding at scale. For developers building SEO tooling, this changes everything about how we architect systems, process content, and measure success.',
    '<strong>The Paradigm Shift: From Keywords to Concepts</strong>Traditional SEO tooling operates on a simple premise: extract keywords, track rankings, optimize density. That model is dead. Modern search uses vector embeddings to understand semantic relationships between concepts. When a user searches "best running shoes for flat feet," Google doesn\'t match keywords — it maps the query into a high-dimensional vector space where "flat feet," "overpronation," "arch support," and "stability shoes" cluster together. The results reflect conceptual proximity, not keyword overlap.',
    '<strong>Implication for developers:</strong> Your keyword database is now a liability. You need vector databases (Pinecone, Weaviate, Qdrant) storing content embeddings, not keyword indexes.',
    '<strong>AI-Generated Content: The Quality Threshold</strong>Google\'s stance has crystallized: AI content isn\'t penalized — low-quality content is, regardless of origin. The March 2024 update specifically targeted "scaled content abuse" whether human or machine-written.',
    '<strong>What Triggers Penalties</strong><ul><li>Thin content: word count < 300 with no unique value</li><li>Template spam: identical structure across 1000+ pages</li><li>No E-E-A-T: no author expertise, experience, authoritativeness, trustworthiness</li><li>Keyword stuffing: unnatural density > 3% for target terms</li><li>Zero original research: purely synthesized from top 10 results</li></ul>',
    '<strong>What Ranks</strong>Content demonstrating E-E-A-T with original data, experiments, or analysis; author credentials and topical authority; unique insights not found in training data; genuine user value beyond answering the query. <strong>Developer takeaway:</strong> Build tooling that augments human expertise — data extraction, fact-checking, structure optimization — not tooling that replaces it.',
    '<strong>Programmatic SEO at Scale: The New Architecture</strong>Modern programmatic SEO isn\'t spinning up 50,000 thin pages. It\'s data-driven content generation where each page has unique, valuable entity relationships.',
    '<strong>The Architecture</strong>Entity-first approach: structured data + unstructured content + third-party APIs + user signals → entity extraction & linking (NER + LLM entity resolution, knowledge graph construction, relationship mapping) → content generation pipeline (template selection, LLM enhancement, human review gate) → validation layer (fact-checking against knowledge graph, E-E-A-T scoring, duplicate detection via embedding cosine similarity, brand voice compliance) → deployment (ISR, edge caching, real-time indexing API).',
    '<strong>Implementation Pattern: Entity-First Content</strong>Instead of keyword-based templates, build entity relationships with typed attributes, relationships, search intent, and content requirements (min word count, required sections, data points, expert review flags, update frequency). See the full TypeScript implementation in our repository.',
    '<strong>Semantic Search & Vector Embeddings: Implementation</strong>Choosing an embedding model: text-embedding-3-large (3072 dim, highest quality) for production search; text-embedding-3-small (1536 dim, fast) for high-volume; bge-large-en-v1.5 or e5-large-v2 for self-hosted/open-source needs.',
    '<strong>Hybrid Search: The Production Pattern</strong>Pure vector search fails on exact-match queries. Pure keyword search fails on semantic queries. Hybrid is mandatory. Reciprocal Rank Fusion (RRF) combines vector and BM25 results with configurable weights. Code implementation included in the full article.',
    '<strong>Chunking Strategy for SEO Content</strong>Semantic chunking preserves entity relationships — chunk by heading boundaries, not fixed token counts. Add contextual overlap (50 tokens) for context preservation.',
    '<strong>AI-Powered Keyword Research: Beyond Volume</strong>Traditional tools give volume and difficulty. They don\'t give intent clusters, content gaps, or semantic coverage. Use LLMs for intent clustering: group keywords by search intent and topical affinity, returning cluster name, intent type, primary/secondary keywords, content type, volume estimates, difficulty scores.',
    '<strong>Content Gap Analysis at Scale</strong>Fetch competitor sitemaps, embed content, cluster embeddings into topics, map your coverage, identify gaps weighted by traffic potential. Prioritize by estimated traffic × conversion value ÷ difficulty.',
    '<strong>Technical SEO Automation: AI Agents for Maintenance</strong>Automated technical audits combine rule-based checks (fast, deterministic) with LLM analysis for complex patterns: topical authority gaps, internal linking opportunities, content cannibalization, schema markup opportunities, Core Web Vitals patterns by template.',
    '<strong>Automated Schema Markup Generation</strong>Generate JSON-LD from content structure + entity data: WebPage/Article base, entity-specific schemas (Product, Comparison, FAQ), BreadcrumbList. All typed, validated, deployed automatically.',
    '<strong>Measuring What Matters: New KPIs</strong>Traditional rank tracking is insufficient. Semantic visibility score measures visibility across topic clusters weighted by search volume, intent value, and SERP feature ownership. Business outcome correlation connects SEO metrics to revenue via attribution modeling.',
    '<strong>Building Your AI-SEO Stack</strong>Core components: Vector DB (Pinecone/Weaviate/Qdrant/pgvector), Embeddings (OpenAI/Cohere/BGE), LLM Orchestration (LangChain/LlamaIndex/custom), Keyword Data (DataForSEO/Semrush/Ahrefs + custom clustering), Crawling (Screaming Frog/Playwright), Indexing (IndexNow/Google Indexing API), Observability (PostHog/custom dashboards). Docker compose for local dev included.',
    '<strong>Pitfalls to Avoid</strong><ul><li>Over-relying on LLMs for fact generation — feed verified data, ask for synthesis</li><li>Ignoring crawl budget on AI-generated pages — implement smart crawl budget allocation with human review gates</li><li>Single-embedding fallacy — content needs multiple embeddings for different retrieval tasks (semantic search, classification, deduplication, clustering)</li></ul>',
    '<strong>The Competitive Moat: Proprietary Data + AI</strong>The winners in 2026 SEO aren\'t those with the best prompts — they\'re those with proprietary data that LLMs can\'t access: original research data, structured product/service data, user behavior data, expert knowledge, local/geo data. Example: comprehensive running shoe database with lab test results, market pricing, usage intelligence, expert consensus — data no LLM has in training.',
    '<strong>Implementation Roadmap</strong>Phase 1 (Weeks 1-4): Vector DB + embedding pipeline, hybrid search, entity extraction + knowledge graph, semantic chunking. Phase 2 (Weeks 5-8): Intent clustering, content gap analysis, automated technical audit with LLM analysis, schema markup pipeline. Phase 3 (Weeks 9-12): Human-in-the-loop content generation, E-E-A-T validation, ISR deployment, real-time indexing. Phase 4 (Weeks 13-16): Semantic visibility tracking, business outcome correlation, automated reporting + alerting, A/B testing AI-assisted vs human-only content.',
    '<strong>Conclusion</strong>AI hasn\'t killed SEO — it\'s raised the floor and removed the ceiling. The floor: generic, keyword-stuffed, thin content now ranks nowhere. The ceiling: teams combining proprietary data + AI orchestration + human expertise can produce comprehensive, accurate, updating-at-scale content that dominates entire topic clusters. Your SEO system should understand topical landscapes semantically, identify high-value gaps with business impact, orchestrate human+AI content creation with quality gates, measure semantic visibility tied to revenue, and compound proprietary data assets over time. The tools are available. The architecture is clear. The moat is yours to build.',
    '<strong>Quick Reference</strong>Essential APIs: OpenAI Embeddings ($0.0001/1K tokens), Cohere Rerank ($1/1K searches), DataForSEO (pay-per-request), IndexNow (free), Google Indexing API (free quota). Key papers: Google Search Quality Rater Guidelines (E-E-A-T), Dense Passage Retrieval (Karpukhin et al.), Reciprocal Rank Fusion (Cormack et al.), Lost in the Middle (Liu et al.), RAG vs Fine-tuning (Wu et al.).',
  ] },
  { slug: 'why-kenyan-business-needs-professional-website-2026', type: 'article', title: 'Why Every Kenyan Business Needs a Professional Website in 2026', excerpt: 'A professional website is no longer optional — it is the foundation of credibility, customer acquisition, and growth for Kenyan businesses. Here is why the businesses investing now are pulling ahead.', category: 'Business & Digital Transformation', date: '2026-09-28', readTime: '8 min read', author: 'Lumyn Studio', image: '/images/articles/website-need-hero.svg', cluster: 'business-website', relatedSlugs: ['website-cost-kenya-2026', 'custom-website-vs-wordpress-kenya', 'website-vs-social-media-kenya'], faq: [
    { question: 'Do I need a website if I have a Facebook/Instagram page?', answer: 'Yes. Social media is a channel you don\'t own — algorithms control reach, no search visibility, no permanence. A website is the only digital asset you fully own and build equity in.' },
    { question: 'How much does a professional website cost in Kenya?', answer: 'KES 15,000–80,000/yr (DIY), KES 80,000–400,000 (freelancer), KES 400,000–1,500,000 (agency), KES 1,500,000+ (custom platform). Hidden costs add 20–30%.' },
    { question: 'What makes a website "professional" in 2026?', answer: 'Custom domain, SSL/HTTPS, mobile-first responsive, <3s load time, working contact forms, GA/GSC configured, schema markup, CMS for self-updates, content answering real customer questions.' },
    { question: 'Does my website need M-Pesa integration?', answer: 'Expected by customers. Native STK Push with callback handling converts 30–50% better than redirecting to till numbers. Integrate Pesapal, IntaSend, or direct Safaricom APIs.' },
    { question: 'How does local SEO help my Kenyan business?', answer: 'Google Business Profile + structured data + reviews = visibility for "plumber in Westlands" searches. Lowest CAC acquisition channel with 12–24 month compound returns.' },
  ], content: [
    'In 2026, a Kenyan business without a professional website is invisible to the customers who matter most — the ones searching, comparing, and deciding before they ever pick up the phone.',
    '<strong>The credibility gap is real.</strong> A 2025 GeoPoll survey found that 78% of Kenyan consumers research a business online before making a purchase or visiting a physical location. When they search and find nothing — or a neglected Facebook page with outdated hours — the assumption is not "this business is busy." The assumption is "this business is not serious."',
    '<strong>WhatsApp and social media are not a digital strategy.</strong> They are channels. A channel you do not own, governed by algorithms you cannot control, with no search visibility and no permanence. A professional website is the only digital asset you fully own, control, and can build equity in over time.',
    '<strong>Local search has changed the game.</strong> Google Business Profile and local SEO mean that when someone searches "plumber in Westlands" or "lawyer in Karen," the businesses showing up are the ones with optimized websites, structured data, and consistent citations. The businesses without websites do not appear — period.',
    '<strong>Mobile-first is not a trend in Kenya. It is the baseline.</strong> Over 95% of internet access in Kenya is mobile. A professional website in 2026 means fast loading on 3G/4G, responsive design that works on a KES 15,000 smartphone, and click-to-call, click-to-WhatsApp, and click-to-map actions that work natively.',
    '<strong>Payment integration is now expected.</strong> Customers expect to pay via M-Pesa, card, or bank transfer directly on your site. A professional website with integrated payment flows (M-Pesa STK Push, Pesapal, IntaSend, or bank APIs) converts browsers into buyers without forcing them to leave your ecosystem.',
    '<strong>The cost of not having one is higher than the cost of building one.</strong> A professional website in Kenya ranges from KES 80,000 (custom freelancer build) to KES 1,500,000+ (agency product-grade platform). The revenue lost from missed leads, lost credibility, and invisible search presence over 12 months almost always exceeds the build cost.',
    '<strong>What "professional" actually means in 2026:</strong>',
    '<ul><li>Custom domain (yourbusiness.co.ke or .com)</li><li>SSL certificate and HTTPS everywhere</li><li>Clear value proposition above the fold</li><li>Mobile-first responsive design</li><li>Fast load times (under 3 seconds on mobile)</li><li>Contact forms that actually work and route to the right person</li><li>Google Analytics and Search Console configured</li><li>Schema markup for local business, services, and reviews</li><li>Content that answers real customer questions</li><li>A CMS your team can update without a developer</li></ul>',
    '<strong>The businesses winning in 2026 treat their website as a product, not a project.</strong> They measure traffic, track conversions, A/B test headlines, update content monthly, and integrate with their CRM and WhatsApp Business API. They iterate. The businesses treating it as a one-time brochure are already falling behind.',
    'If your website does not exist, is outdated, or was built on a platform you cannot control, the best time to fix it was two years ago. The second best time is today. If the question is only whether you can get away with social media for now, <a href="/articles/website-vs-social-media-kenya">website vs social media</a> is the honest comparison. For the short version of what to insist on, see <a href="/articles/10-features-every-business-website-should-have">the ten features every business website should have</a>. Then <a href="/contact">talk to our team</a> about building a website that works as hard as your business does.',
  ] },
  { slug: 'building-digital-products-for-africa', type: 'article', title: 'Building digital products for Africa\'s next chapter', excerpt: 'The strongest products start with a close understanding of the people, infrastructure, and ambition they are built for.', category: 'Product', date: '2026-09-18', readTime: '8 min read', author: 'Lumyn Studio', image: '/images/articles/africa-products-hero.svg', cluster: 'kenya-digital-economy', relatedSlugs: ['state-of-digital-business-kenya-2026', 'mpesa-integration-lessons'], content: [
    'Africa is not a single market. It is a collection of ambitious, fast-moving ecosystems where technology meets real constraints and real opportunity.',
    'From Lagos to Nairobi to Cape Town, the same pattern shows up: the teams that win are the ones that treat infrastructure as a design constraint, not an afterthought.',
    '<strong>Design for the network you have, not the network you want</strong>In Nairobi, 4G coverage is solid in the CBD but drops to 2G/3G in informal settlements. In Lagos, data costs remain high relative to income. In Cape Town, load shedding means your app must work offline-first or gracefully degrade. Building for "average" conditions means failing for the majority.',
    '<strong>Payment is not a feature — it is the product</strong>In Kenya, M-Pesa is not a payment method; it is the financial operating system. In Nigeria, bank transfers and USSD dominate. In Ghana, MoMo. In Egypt, Fawry. A checkout that redirects to a web view loses 40% of users. Native STK Push, USSD fallbacks, and instant reconciliation are table stakes.',
    '<strong>Language and literacy are product decisions</strong>Swahili, Sheng, Yoruba, Pidgin, Zulu, Arabic — your users think in these languages. English-only interfaces create cognitive load and exclusion. Voice notes, icon-heavy navigation, and progressive disclosure beat text-heavy tutorials every time.',
    '<strong>Trust is earned in the details</strong>With digital fraud rising 40% YoY (CAK), users verify before they transact: Truecaller badges, Google reviews, WhatsApp Business verification, visible company registration, SSL certificates. Products that invest in trust signals — transparent pricing, clear escalation paths, responsive support — convert 2–3x higher.',
    '<strong>Distribution is harder than development</strong>The App Store and Play Store are not primary discovery channels for most African users. WhatsApp forwards, TikTok demos, boda-boda referral codes, agent networks, and USSD shortcodes drive adoption. Build distribution into the product: referral loops, offline onboarding, agent dashboards.',
    '<strong>Local partnerships > global playbooks</strong>Silicon Valley frameworks assume reliable infrastructure, high ARPU, and homogeneous users. African products need local ops partners: logistics (Sendy, Lori), identity (Smile Identity, Prembly), credit scoring (Lendsqr, Migo), agent networks. The best products embed these, not rebuild them.',
    '<strong>What this means for product teams</strong>',
    '<ul><li>Hire locally. Your PM, designer, and engineer should use the product daily on the same networks as your users.</li><li>Test on KES 15,000 devices. If it works on a Tecno Spark on 3G, it works everywhere.</li><li>Measure what matters: completion rate on 2G, offline task success, referral coefficient, agent activation — not just DAU/MAU.</li><li>Build for the informal economy. The 80% of SMEs still on cash and notebooks are your biggest TAM.</li></ul>',
    'At Lumyn, we design around those realities: resilient infrastructure, thoughtful payment experiences, and interfaces that make complex work feel simple. The result is digital work that does more than look good. It creates momentum for the people and businesses using it.',
    '<strong>Ready to build for Africa\'s reality?</strong> <a href="/contact">Talk to our team</a> about your product challenge.',
  ] },
  { slug: 'mpesa-integration-lessons', type: 'article', title: 'What three M-Pesa integrations taught us about resilient systems', excerpt: 'Reliable payment experiences are built on clear states, graceful retries, and trust at every step.', category: 'Engineering', date: '2026-09-10', readTime: '8 min read', author: 'Lumyn Engineering', image: '/images/articles/mpesa-hero.svg', cluster: 'kenya-digital-economy', relatedSlugs: ['state-of-digital-business-kenya-2026', 'building-digital-products-for-africa', '10-features-every-business-website-should-have'], faq: [
    { question: 'What is the most common M-Pesa integration failure?', answer: 'Timeout handling. Network delays cause callbacks to arrive late or not at all. Implement idempotency keys, exponential backoff retries, and a reconciliation job to catch missed confirmations.' },
    { question: 'Should I use STK Push or B2C for payouts?', answer: 'STK Push for customer-initiated payments (checkout). B2C for business-initiated payouts (refunds, commissions, salaries). They have different APIs, limits, and failure modes.' },
    { question: 'How do I handle M-Pesa callback verification?', answer: 'Verify the callback origin (Safaricom IPs), validate the checksum/hash, check transaction status against your DB before updating, and log everything for audit.' },
    { question: 'What is a circuit breaker and why do I need one?', answer: 'Stops retrying when failure rate exceeds a threshold (e.g., 50% in 1 minute). Prevents cascading failures during Safaricom outages. Resume automatically after cooldown.' },
  ], content: [
    'Payments are the moment a digital promise becomes tangible. That is why reliability matters more than cleverness.',
    'Over three integrations we learned the same lesson three times: a payment system is only as good as its failure handling. Here is what that actually looks like.',
    '<strong>Lesson 1 — Make the state machine explicit.</strong>Every payment has a life cycle: initiated, submitted, confirmed, completed, failed, and reversed. We modelled these as an enum with strict transitions. A payment in "confirmed" cannot jump to "failed" — it must pass through "reversed". This sounds obvious until you realize most bugs come from implicit states.',
    '<strong>Lesson 2 — Retry like a human would.</strong>Network timeouts are rarely permanent. We added exponential backoff with jitter, capped at three attempts, and a circuit breaker that pauses retries if the failure rate crosses 50% in a rolling minute. The key rule: never retry a customer-initiated action more than the user can see.',
    '<strong>Lesson 3 — Tell the user what happened.</strong>When a transaction fails, the message must name the cause. "Payment failed" is useless. "M-Pesa timed out — please check your phone and confirm, or try again" is actionable. We instrumented every failure with a code and surfaced it in the UI.',
    '<strong>Lesson 4 — Reconciliation is not optional.</strong>Safaricom callbacks can arrive out of order, duplicate, or not at all. We built a nightly reconciliation job that compares our ledger against Safaricom\'s settlement reports. Mismatches trigger alerts and manual review. Without this, you will lose money silently.',
    '<strong>Lesson 5 — Idempotency keys everywhere.</strong>Every STK Push request carries a client-generated idempotency key (UUID v4). Safaricom echoes it back in the callback. Our API layer deduplicates on this key before any state change. This prevents double-charges when users hammer the "pay" button or network retries fire.',
    '<strong>Lesson 6 — Observability pays for itself.</strong>We log every state transition, every callback payload, every retry attempt, every reconciliation mismatch. Dashboards show: success rate by hour, callback latency p50/p95/p99, retry distribution, circuit breaker state. When Safaricom has an incident, we know before support tickets arrive.',
    '<strong>Lesson 7 — Test with production-like chaos.</strong>Our CI pipeline includes chaos tests: simulated Safaricom downtime, callback delays (0–120s), duplicate callbacks, malformed payloads, network partitions. Tests must pass before merge. This catches regressions that unit tests miss.',
    'Our approach pairs clear transaction states with safe retries, useful observability, and copy that helps people understand what happened. These patterns travel well beyond one provider. They are the foundation of every dependable commerce experience.',
    '<strong>Reference implementation:</strong> See our open-source <a href="https://github.com/lumyn/mpesa-resilient-client" target="_blank" rel="noopener">mpesa-resilient-client</a> for a production-ready TypeScript client with all these patterns baked in.',
  ] },
  { slug: 'the-lumyn-studio-system', type: 'article', title: 'Inside the Lumyn Studio system', excerpt: 'A practical look at how we turn strategy, design, and engineering into one focused delivery system.', category: 'Studio', date: '2026-08-28', readTime: '7 min read', author: 'Lumyn Studio', image: '/images/articles/studio-system-hero.svg', cluster: 'studio-process', relatedSlugs: [], content: [
    'Great work is rarely the result of one discipline working alone. Our studio brings strategy, design, and engineering into the same conversation from day one.',
    'The traditional model separates these into phases: strategy first, then design, then engineering. That works when the problem is well understood. It breaks down when it is not.',
    '<strong>Why the phased model fails</strong>In a phased handoff, strategy writes a brief that design interprets into mockups that engineering discovers are unbuildable within constraints. By the time engineering pushes back, weeks are lost. The brief was wrong, but nobody knew until code hit reality.',
    '<strong>Our approach: one room, one conversation</strong>Strategy defines the problem and the north star. Design sketches the shape of the solution. Engineering validates what is actually buildable — and often feeds that back to reshape the problem. This happens in the same room, in real time, not across Jira tickets.',
    '<strong>Three pillars of the system</strong>',
    '<ul><li><strong>Strategy:</strong> Market research, user interviews, competitive audit, north-star metrics, success criteria. We don\'t just ask "what do you want?" — we ask "what outcome changes your business?"</li><li><strong>Design:</strong> Not pixels first. Systems first: design tokens, component library, motion language, accessibility baseline. Then high-fidelity flows validated with real users before a line of production code.</li><li><strong>Engineering:</strong> Type-safe from day one (TypeScript, strict mode). Shared component library with design. CI/CD with preview deployments for every PR. Observability (Sentry, PostHog) baked in, not bolted on.</li></ul>',
    '<strong>The delivery loop</strong>Two-week sprints with a fixed cadence: Monday planning → Wednesday mid-sprint sync → Friday demo + retro. Stakeholders see working software every Friday. Scope is variable; quality and date are fixed. This creates fewer handoffs, sharper decisions, and a more honest relationship between the idea and the shipped product.',
    '<strong>When we break the system</strong>Fixed-scope, fixed-date, fixed-budget projects (agency model) force trade-offs we won\'t make. We decline those. We also decline "design-only" or "dev-only" engagements — the magic is in the integration.',
    '<strong>Results this system produces</strong>Dwell KE: property discovery platform with map search, saved searches, agent dashboards, M-Pesa booking — delivered in 14 weeks. Law firm client: WordPress site with custom legal guide taxonomy, multi-author workflow — delivered in 6 weeks. Both correct decisions, both from the same system.',
    '<strong>We call it a system because it is repeatable.</strong> Each project is different, but the standards stay high. The team composition flexes, the tools evolve, but the principle — strategy, design, engineering in one conversation — does not change.',
    '<strong>Want to see how this works for your project?</strong> <a href="/contact">Start a conversation</a> and we\'ll walk you through the approach.',
  ] },
  { slug: 'lumyn-launches-new-brand-system', type: 'news', title: 'Lumyn launches a new digital brand system', excerpt: 'A sharper visual language for a company building what comes next.', category: 'Company News', date: '2026-09-20', readTime: '2 min read', author: 'Lumyn Technologies', image: '/images/articles/brand-launch-hero.svg', content: [
    'Today we are introducing a new brand system built around clarity, energy, and useful technology.',
    'The system brings our products, studio work, and stories together under one recognizable point of view.',
  ] },
  { slug: 'lumyn-hosts-builders-night', type: 'news', title: 'Lumyn hosts Nairobi builders night', excerpt: 'Local makers gathered to share ideas, prototypes, and practical lessons from the work.', category: 'Events', date: '2026-09-05', readTime: '2 min read', author: 'Lumyn Technologies', image: '/images/articles/builders-night-hero.svg', content: [
    'Builders Night brought together designers, engineers, founders, and curious minds for an evening of honest conversations.',
    'We left with new questions, new collaborators, and a renewed belief in the power of sharing the work.',
  ] },
  { slug: 'website-cost-kenya-2026', type: 'article', title: 'How Much Does a Website Cost in Kenya in 2026?', excerpt: 'A realistic breakdown of what Kenyan businesses pay for a website in 2026 — from DIY builders to custom platforms — and what drives the difference.', category: 'Product', date: '2026-09-25', dateModified: '2026-09-28', readTime: '7 min read', author: 'Lumyn Studio', image: '/images/articles/website-cost-hero.svg', cluster: 'business-website', relatedSlugs: ['why-kenyan-business-needs-professional-website-2026', 'custom-website-vs-wordpress-kenya', 'how-to-choose-web-development-company-kenya'], faq: [
    { question: 'What is the cheapest way to get a website in Kenya?', answer: 'DIY builders like Wix or WordPress.com starting at KES 15,000/year. Best for simple brochure sites with 5 pages or fewer.' },
    { question: 'How much does a custom website cost in Kenya?', answer: 'KES 400,000–2,500,000+ depending on complexity. Agencies charge KES 400K–1.5M; custom platforms (SaaS, marketplaces) start at KES 1.5M.' },
    { question: 'Are there hidden costs beyond the initial quote?', answer: 'Yes. Domain (KES 2,500–4,000/yr), hosting (KES 3,000–15,000/yr), SSL, professional copy/photos (KES 30K–100K), ongoing SEO/maintenance. Budget 20–30% extra.' },
    { question: 'Should I hire a freelancer or agency?', answer: 'Freelancers (KES 80K–400K) are cheaper but risk continuity. Agencies (KES 400K–1.5M) provide project management, accountability, and support. Verify portfolio before hiring.' },
  ], content: [
    'Short answer: anywhere from KES 15,000 for a basic template site to KES 2,500,000+ for a custom enterprise platform. The honest answer is more useful. Here is what actually drives cost in the Kenyan market in 2026.',
    '<strong>The four cost levers.</strong>Every quote you receive breaks down into four things: design complexity, engineering effort, integrations, and ongoing maintenance. A cheap site saves on design and engineering. An expensive one spends on all four — and usually on integrations you did not plan for.',
    '<strong>DIY and template builders: KES 15,000 – 80,000 per year.</strong>Wix, Squarespace, and WordPress.com handle hosting, security, and updates for you. You trade control for speed. This works for a brochure site — five pages, a contact form, a Google map. It stops working when you need M-Pesa payments, a member portal, or a custom admin panel. Budget one to two weeks of your own time to set it up properly.',
    '<strong>Freelancer-developed sites: KES 80,000 – 400,000.</strong>Most Kenyan businesses land here. You get a custom design, a CMS you can edit yourself, and a handful of integrations — booking system, newsletter, social feeds. The risk is not the price. It is continuity: when the freelancer disappears or their package expires, you own a site you cannot update. Ask for the source files, the CMS credentials, and a handover document before you pay the final instalment.',
    '<strong>Agency work: KES 400,000 – 1,500,000.</strong>Agencies bundle strategy, design, engineering, and support into one engagement. You get a project manager, a defined timeline, and someone accountable if something breaks. The premium you pay above a freelancer is mostly for reduced risk and faster delivery. Verify the agency has shipped work similar to yours before you sign.',
    '<strong>Custom platforms: KES 1,500,000 – 2,500,000+.</strong>This is product-grade software: multi-tenant dashboards, real-time reporting, M-Pesa integration with reconciliation, role-based access, and an SLA. Nobody builds this on a template. Most projects at this level also carry an annual support contract of 10–20% of the build cost. Budget for it or expect to rewrite the system in two years.',
    '<strong>Hidden costs nobody quotes.</strong>Domain registration (KES 2,500–4,000 per year), hosting (KES 3,000–15,000 per year depending on traffic), an SSL certificate, professional photography or copywriting (KES 30,000–100,000), and ongoing SEO. A KES 500,000 website realistically costs KES 650,000–750,000 all-in over three years once these are included.',
    '<strong>How to get a fair quote fast.</strong>Agencies and freelancers price from a brief. Give them: your goals, the pages you need, the integrations you cannot do without, your target launch date, and your budget range. Vague briefs get vague quotes. A specific brief gets you a number you can actually plan around.',
    'The right question is not "how much does a website cost". It is "what do I need the website to do, and what is the cheapest way to get there without owning a liability I cannot operate". If you already know the range and now need to pick who builds it, <a href="/articles/how-to-choose-web-development-company-kenya">how to choose a web development company in Kenya</a> covers the questions and contract clauses that separate the two. If that sounds like your situation, <a href="/contact">start a conversation with our team</a> and we will give you an honest range, not a fantasy.',
  ] },
  { slug: 'custom-website-vs-wordpress-kenya', type: 'article', title: 'Custom Website vs WordPress: Which Is Right for Your Business?', excerpt: 'WordPress powers 43% of the web, but custom development still wins for specific use cases. A practical decision framework for Kenyan businesses choosing between the two paths.', category: 'Web Development & Technology', date: '2026-09-29', readTime: '9 min read', author: 'Lumyn Engineering', image: '/images/articles/wp-vs-custom-hero.svg', cluster: 'business-website', relatedSlugs: ['why-kenyan-business-needs-professional-website-2026', 'website-cost-kenya-2026', '10-features-every-business-website-should-have'], faq: [
    { question: 'Is WordPress cheaper than custom development?', answer: 'Initially, yes. WordPress sites cost KES 80K–400K vs KES 400K+ for custom. But 3-year TCO often favors custom due to zero plugin licenses, no forced upgrades, and lower maintenance.' },
    { question: 'Can WordPress handle M-Pesa payments?', answer: 'Yes, via WooCommerce with Pesapal or IntaSend plugins. Works for standard e-commerce. Custom STK Push flows, reconciliation dashboards, or split payments need custom development.' },
    { question: 'What if I need to scale later?', answer: 'WordPress scales with effort (caching, CDN, database optimization). Custom Next.js/React scales natively on Vercel/Cloudflare. For high-traffic SaaS or marketplaces, custom wins long-term.' },
    { question: 'Do I own my WordPress site?', answer: 'You own the content and database, but not the platform. Plugin licenses, PHP/MySQL versions, and hosting constraints create vendor lock-in. Custom code gives full IP ownership.' },
  ], comparisonTable: {
    caption: 'WordPress vs Custom Development — Kenya 2026 Decision Factors',
    headers: ['Factor', 'WordPress', 'Custom (Next.js/React)'],
    rows: [
      ['Upfront Cost', 'KES 80K–400K', 'KES 400K–2.5M+'],
      ['3-Year TCO', 'Higher (plugin licenses, hosting, maintenance)', 'Lower (zero license fees, simpler stack)'],
      ['M-Pesa Integration', 'Via plugins (Pesapal/IntaSend)', 'Native STK Push, custom flows, reconciliation'],
      ['Performance (TTFB)', '800ms–2s (shared hosting)', '50–150ms (Vercel/Cloudflare edge)'],
      ['Security Surface', 'High (20–40 plugins avg, 97% vulns from plugins)', 'Minimal (only your code)'],
      ['Scaling', 'Manual (caching, DB optimization, CDN)', 'Native (edge, serverless, auto-scale)'],
      ['IP Ownership', 'Platform-dependent', 'Full ownership'],
      ['Team Required', 'Marketing/Content team', 'Engineering team'],
      ['Best For', 'Content-led, standard e-commerce, budgets < KES 400K', 'SaaS, marketplaces, complex integrations, high traffic'],
    ],
  }, content: [
    'The short answer: WordPress is the right choice for content-led businesses that need editorial control and a vast plugin ecosystem. Custom development wins when you need unique workflows, complex integrations, performance at scale, or full ownership of your technology stack.',
    '<strong>Where WordPress makes sense in Kenya:</strong>',
    '<ul><li>Service businesses (law firms, agencies, consultants) where the site is primarily a brochure + blog + contact form</li><li>Content publishers (news, blogs, media) who need multi-author workflows, scheduling, and taxonomy</li><li>E-commerce stores with standard product catalogs — WooCommerce handles M-Pesa via Pesapal/IntaSend plugins</li><li>Teams with limited technical capacity who need non-developers to update content daily</li><li>Budgets under KES 400,000 where you need maximum features per shilling</li></ul>',
    '<strong>Where custom development (Next.js, React, Vue, Laravel, Django) wins:</strong>',
    '<ul><li>Marketplaces and platforms (like Enkaji) with multi-sided user roles, complex search, and transaction flows</li><li>SaaS products requiring custom dashboards, real-time data, API-first architecture</li><li>High-traffic applications where Core Web Vitals and server-side rendering directly impact revenue</li><li>Complex integrations — ERP sync, custom M-Pesa STK Push flows, bank API reconciliation, CRM automation</li><li>Businesses building IP they need to own, license, or sell — you cannot "own" a WordPress site the same way</li><li>Long-term cost control — no plugin license renewals, no forced PHP/MySQL upgrades, no vendor lock-in</li></ul>',
    '<strong>The hidden costs that change the calculation:</strong>',
    '<ul><li><strong>Plugin debt:</strong> The average WordPress site runs 20–40 plugins. Each is a maintenance liability, a security surface, and a potential conflict. Custom code has zero plugin debt.</li><li><strong>Performance ceiling:</strong> WordPress on shared hosting hits TTFB of 800ms–2s. Custom Next.js on Vercel/Netlify/Cloudflare hits 50–150ms. For e-commerce, every 100ms delay costs ~1% conversion (Google data).</li><li><strong>Security ownership:</strong> WordPress core is secure; the ecosystem is not. 97% of WordPress vulnerabilities come from plugins/themes (WPScan 2024). Custom apps only expose the attack surface you deliberately build.</li><li><strong>Developer availability:</strong> Kenya has abundant WordPress freelancers. Senior custom-stack engineers are scarcer and cost 2–3x more per hour — but you need fewer hours for a focused build.</li></ul>',
    '<strong>Decision framework — answer these 5 questions:</strong>',
    '<ol><li><strong>Is content publishing your primary activity?</strong> Yes → WordPress. No → continue.</li><li><strong>Do you need user accounts, dashboards, or multi-step workflows?</strong> Yes → Custom. No → continue.</li><li><strong>Are your integrations standard (WooCommerce + Pesapal) or custom (bank APIs, ERP, proprietary CRM)?</strong> Custom → Custom build. Standard → WordPress works.</li><li><strong>What is your 3-year horizon?</strong> If you are building a product to scale, raise funding, or exit → Custom. If the site serves a stable local business → WordPress.</li><li><strong>Who owns updates?</strong> Marketing team daily → WordPress. Engineering team sprints → Custom.</li></ol>',
    '<strong>Real Lumyn perspective:</strong> We build both. Dwell KE runs on Next.js with a custom CMS because property discovery needs map-based search, saved searches, agent dashboards, and M-Pesa booking flows that no plugin handles cleanly. A law firm client runs WordPress because they publish three legal guides a week and need the editorial team to self-serve. Both are correct decisions.',
    '<strong>The hybrid path:</strong> Some teams run WordPress for marketing pages (blog, landing pages, SEO content) and a custom Next.js/React app for the authenticated product experience — connected via shared authentication and design system. This works when the marketing velocity and product complexity justify the split.',
    'Still unsure? <a href="/contact">Share your brief</a> and we will map your requirements to the right architecture — no bias toward either stack.',
  ] },
  { slug: 'state-of-digital-business-kenya-2026', type: 'article', title: 'The State of Digital Business in Kenya in 2026', excerpt: 'Kenya\'s digital economy is maturing fast — mobile money ubiquity, a growing startup ecosystem, and shifting consumer behavior. A data-grounded look at where the market stands and what it means for businesses going digital.', category: 'Kenyan Business & Digital Economy', date: '2026-09-30', readTime: '10 min read', author: 'Lumyn Studio', image: '/images/articles/kenya-digital-hero.svg', cluster: 'kenya-digital-economy', relatedSlugs: ['building-digital-products-for-africa', 'why-kenyan-business-needs-professional-website-2026'], faq: [
    { question: 'What is the internet penetration in Kenya in 2026?', answer: '~45% (23M+ users), growing 6% YoY per CAK 2025 data. Mobile subscriptions exceed 68M (130% penetration, multi-SIM).' },
    { question: 'Is M-Pesa still the dominant payment method?', answer: 'Yes. 38M+ active users, KES 7.2T+ annual volume (Safaricom FY25). STK Push, B2C, B2B, Express APIs are commoditized — competitive edge is now reconciliation, split payments, cross-border, embedded finance.' },
    { question: 'What are the biggest digital opportunities in Kenya?', answer: 'Bridging informal-to-formal: 80% of SMEs still run on cash/paper. They need simple, Swahili/Sheng-supported, offline-capable tools for inventory, payments, credit.' },
    { question: 'How important is WhatsApp Business for Kenyan SMEs?', answer: 'Critical. WhatsApp Business API, Instagram DM automation, TikTok affiliate programs are core sales channels — not afterthoughts. Chat is becoming checkout.' },
    { question: 'What regulatory changes affect digital businesses?', answer: 'Data Protection Act (2019) enforcement active with ODPC fines. CBK sandbox for fintech. ICTA digital masterplan pushing e-government (eCitizen, NTSA, KRA iTax) — B2G integration increasingly required.' },
  ], content: [
    'Kenya in 2026 is not "going digital." It is digital. The question is no longer whether your business needs an online presence — it is whether your digital presence is keeping pace with how Kenyans actually buy, sell, and transact today.',
    '<strong>The numbers that matter:</strong>',
    '<ul><li><strong>Internet penetration:</strong> ~45% (23M+ users), growing 6% YoY (CAK 2025)</li><li><strong>Mobile subscriptions:</strong> 68M+ — 130% penetration, multiple SIMs per user</li><li><strong>Smartphone adoption:</strong> ~60% of connections, driven by sub-KES 15,000 devices (Transsion, Xiaomi, Samsung A-series)</li><li><strong>Mobile money:</strong> 38M+ active M-Pesa users, KES 7.2T+ annual volume (Safaricom FY25)</li><li><strong>E-commerce:</strong> Estimated KES 300B+ GMV across formal and informal channels (UNCTAD/KNBS estimates)</li><li><strong>Digital lending:</strong> 15M+ borrowers across M-Shwari, Fuliza, Tala, Branch, Zenka — credit history now digital by default</li></ul>',
    '<strong>Three structural shifts defining 2026:</strong>',
    '<strong>1. Commerce has moved to chat and social.</strong> WhatsApp Business, Instagram Shops, TikTok Shop, and Facebook Marketplace are where discovery and transaction happen for millions of Kenyan SMEs. The "website as catalog" model is being disrupted by "chat as checkout." Businesses winning in 2026 treat WhatsApp Business API, Instagram DM automation, and TikTok affiliate programs as core sales channels — not afterthoughts.',
    '<strong>2. Payment infrastructure is no longer a differentiator — it is table stakes.</strong> M-Pesa STK Push, B2C, B2B, and Express APIs are commoditized. The competitive edge has shifted to: reconciliation automation, split payments for marketplaces, cross-border (M-Pesa Global, PesaLink, Visa Direct), and embedded finance (lending at checkout, BNPL via Lipa Later/Aspira). If your checkout still redirects to a till number, you are losing 30–50% of intent.',
    '<strong>3. Trust is the new currency.</strong> With digital fraud rising (CAK reports 40% YoY increase in cybercrime), Kenyan consumers verify before they buy: Google reviews, Truecaller tags, WhatsApp Business verification badges, SSL certificates, and visible company registration details. Businesses investing in trust signals — verified profiles, transparent pricing, clear return policies, responsive support — convert 2–3x higher than anonymous storefronts.',
    '<strong>Sector snapshots:</strong>',
    '<ul><li><strong>Retail/FMCG:</strong> Omnichannel is default. Naivas, Carrefour, QuickMart all have apps + WhatsApp ordering + dark store delivery. Informal retailers (dukas) adopting Sokowatch/MarketForce for B2B restocking.</li><li><strong>Real estate:</strong> Property search moved from newspaper classifieds to platforms (Property24, BuyRentKenya, Dwell KE). Virtual tours, agent verification, and M-Pesa booking deposits are standard expectations.</li><li><strong>Logistics/Last-mile:</strong> Sendy, Lori, Kotani, and 50+ boda-based delivery startups. API-first shipping integration is now a feature request, not a luxury.</li><li><strong>AgriTech:</strong> DigiFarm, Twiga, Apollo Agriculture — smallholder financing, input delivery, and market access via USSD/app. 7M+ farmers digitally reachable.</li><li><strong>B2B/Wholesale:</strong> Enkaji, Sokowatch, Copia — digital marketplaces replacing physical wholesale visits. Credit terms, order tracking, and digital invoicing built in.</li></ul>',
    '<strong>The startup ecosystem signal:</strong> Kenya attracted $500M+ in venture funding in 2024 (Partech/Digest Africa), led by fintech, climate tech, and B2B software. The talent pool is deepening — 3,000+ CS graduates annually, 50+ active developer communities, and a growing senior engineering cohort returning from abroad. But the "Series A crunch" is real: investors demand unit economics, not just traction.',
    '<strong>Regulatory landscape:</strong> Data Protection Act (2019) enforcement is active — ODPC fines for non-compliance. CBK sandbox for fintech innovation. ICTA digital masterplan pushing e-government services (eCitizen, NTSA, KRA iTax) — B2G integration is becoming a requirement for government suppliers.',
    '<strong>What this means for your business:</strong>',
    '<ol><li><strong>Mobile-first is not optional.</strong> Your primary user is on a 4-inch screen, 3G/4G, pay-as-you-go data. Every byte and second counts.</li><li><strong>M-Pesa integration must be native, not redirected.</strong> STK Push with callback handling, timeout recovery, and reconciliation dashboards.</li><li><strong>WhatsApp Business API is a sales channel.</strong> Automated catalogs, order tracking, support — integrate it or lose the conversation.</li><li><strong>Local SEO is your lowest-CAC acquisition.</strong> Google Business Profile, structured data, review generation — compound returns over 12–24 months.</li><li><strong>Build for the informal-to-formal bridge.</strong> The biggest opportunity is digitizing businesses that still run on cash, paper, and memory. They need simple, Swahili/Sheng-supported, offline-capable tools.</li></ol>',
    '<strong>Lumyn\'s view from the build floor:</strong> We see two Kenyas — one building world-class SaaS (Lipa Later, Kwara, Apollo) exporting to Africa and beyond, and another where 80% of SMEs still manage inventory on notebooks. The bridge is productized, affordable, locally-supported software. That is what we build. <a href="/contact">If you are crossing that bridge, talk to us.</a>',
  ] },
  { slug: 'synthos-launches-creative-intelligence-platform', type: 'news', title: 'Synthos builds Kenya\'s creative job board and AI-assisted talent marketplace', excerpt: 'Verified employers, curated creative roles, and a 10-stage AI-assisted workflow for urgent projects — Synthos is now in build.', category: 'Company News', date: '2026-10-06', readTime: '2 min read', author: 'Lumyn Technologies', image: '/images/articles/builders-night-hero.svg', content: [
    'Synthos is now in build. The platform is a creative job board and talent marketplace for Kenya — verified employers, curated roles, and AI-assisted project delivery for urgent creative work.',
    'The gap Synthos is solving is real: talented creative professionals and verified employers struggle to find each other in a market where trust and quality are inconsistent. Synthos makes both sides accountable. Creative professionals showcase skills, set rates, and get hired on proven work. Employers post curated roles and build project teams fast.',
    'For urgent projects, Synthos runs a 10-stage AI-assisted workflow that handles the heavy lifting — matching, scoping, and tracking — while humans provide judgment and final approval. AI assists. Humans decide. Full traceability at every step.',
    'The platform is being built for creative agencies, brand teams, production studios, and freelance networks in Kenya and beyond. If you are a creative professional or an employer looking for verified talent, <a href="https://synthos.co.ke">synthos.co.ke</a> is where to watch.',
  ] },
]

export const articles = content.filter((item) => item.type === 'article')
export const news = content.filter((item) => item.type === 'news')
export function getContent(slug: string) { return content.find((item) => item.slug === slug) }
export function formatDate(date: string) { return new Intl.DateTimeFormat('en-KE', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(date)) }